 const u={role:'reception',clinic:'CLINIC_A',doctor:'DR_A',session:'SESSION_A',search:'',notice:null,busy:false,mode:'normal',lastTokens:{},draft:{display_name:'',contact_phone:'',doctor_id:'DR_A',window_id:'W1_A'},dialogAction:null,requestCounter:0};
